/* Generated by safe ES module refactor from the existing js/main.js implementation. */

import * as Core from "../core/index.js";
import { ADMIN_PAGES, PUBLIC_PAGES } from "../core/config.js";
import { clearLegacyClientOverrides } from "../core/storage.js";
import { USER_ROUTE_GUARDS, checkSystemStatus, ensureAdminPageAccess, ensureUserPageAccess } from "../core/guards.js";
import { bindCommonShell } from "../core/theme.js";
import { getCurrentPageName, redirectForRole, resolvePagePath, revealProtectedBody } from "../core/routing.js";
import { clearCurrentUser, getCurrentUser } from "../core/auth.js";
import { showMessage } from "../ui/toast.js";
import { bindSharedAdminModals } from "../ui/modal.js";
import { bindAdminLoginForm, bindKeyboardShortcuts, bindUserForms, handleLogout } from "../features/login.js";
import { loadUserDash } from "../features/userDashboard.js";
import { initCheckoutPage } from "../features/checkout.js";
import { fetchFreePanelPageStatus, startKeepAlivePing } from "../features/freePanel.js";
import { bindDashboardControls, loadAdminDash } from "../features/adminDashboard.js";
import { bindGenerateKeyControls } from "../features/keyGenerator.js";
import { bindOwnerDatabaseControls, loadDbData, loadSystemControls } from "../features/ownerDb.js";

function installLegacyCoreGlobal() {
  window.DSCCore = Core;
}

async function bootstrapPublicPage(pageName) {
  revealProtectedBody();
  const maintenanceActive = await checkSystemStatus();
  if (maintenanceActive) return;

  if (pageName === "freepanel.html") {
    await fetchFreePanelPageStatus();
    return;
  }

  if (pageName === "checkout.html") {
    initCheckoutPage();
    return;
  }

}

async function bootstrapUserProtectedPage(pageName) {
  // 🔒 BLOCK FREE USER FROM CHANGE PAGE
  if (pageName === "change.html") {
    const currentUser = getCurrentUser();

    if (currentUser && currentUser.plan && currentUser.plan.toLowerCase() === "free") {
      showMessage("Upgrade required to change password.", "error");
      window.location.replace(resolvePagePath("Udash.html"));
      return;
    }
  }
  const session = await ensureUserPageAccess(pageName);
  if (!session) return;

  revealProtectedBody();

  const maintenanceActive = await checkSystemStatus();
  if (maintenanceActive) return;

  if (pageName === "Udash.html") {
    await loadUserDash();
  }
}

async function bootstrapUserLoginPage() {
  const currentUser = getCurrentUser();
  if (currentUser) {
    redirectForRole(currentUser.role);
    return;
  }

  revealProtectedBody();
  await checkSystemStatus();
}

function bootstrapAdminPlaceholderPage(pageName) {
  if (pageName === "Alogin.html") {
    revealProtectedBody();
  }
}

async function bootstrapCoreApp() {
  const pageName = getCurrentPageName();

  bindCommonShell(handleLogout);
  bindUserForms();
  bindKeyboardShortcuts();

  if (pageName === "Ulogin.html") {
    await bootstrapUserLoginPage();
    return;
  }

  if (USER_ROUTE_GUARDS[pageName]) {
    await bootstrapUserProtectedPage(pageName);
    return;
  }

  if (ADMIN_PAGES.has(pageName)) {
    bootstrapAdminPlaceholderPage(pageName);
    return;
  }

  if (PUBLIC_PAGES.has(pageName)) {
    await bootstrapPublicPage(pageName);
    return;
  }

  revealProtectedBody();
}

async function bootstrapAdminApp() {
  const pageName = getCurrentPageName();
  if (!["Alogin.html", "Adash.html", "OwnerDB.html", "generateKey.html"].includes(pageName)) return;

  bindSharedAdminModals();

  if (pageName === "Alogin.html") {
    const currentUser = getCurrentUser();
    if (currentUser) {
      redirectForRole(currentUser.role);
      return;
    }

    bindAdminLoginForm();
    return;
  }

  const access = await ensureAdminPageAccess(pageName);
  if (!access) return;

  revealProtectedBody();

  if (pageName === "Adash.html") {
    bindDashboardControls();
    await loadAdminDash();
    return;
  }

  if (pageName === "generateKey.html") {
    bindGenerateKeyControls();
    return;
  }

  if (pageName === "OwnerDB.html") {
    bindOwnerDatabaseControls();
    // 🔥 FIX: Ab hamesha backend se real-time fresh settings load karega
    await loadSystemControls();
    await loadDbData();
  }
}

function startPageAnimation() {
  requestAnimationFrame(() => {
    document.body.classList.add("page-loaded");
  });
}

function syncCurrentPageLabels() {
  document.querySelectorAll("[data-current-page-label]").forEach((label) => {
    const header = label.closest(".site-header");
    const activeLink = header?.querySelector("#primary-menu .nav-link.active");
    const pageLabel = String(activeLink?.textContent || label.dataset.pageLabel || "").trim();
    if (pageLabel) label.textContent = pageLabel;
  });
}

function runBootstraps() {
  syncCurrentPageLabels();
  bootstrapCoreApp();
  startPageAnimation();
  bootstrapAdminApp();
}

export function initializeApp() {
  clearLegacyClientOverrides();
  installLegacyCoreGlobal();

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", runBootstraps);
  } else {
    runBootstraps();
  }

  startKeepAlivePing();
}
